INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "「さすがエリコだね！\n伴侶の僕も、とても\n誇らしいよ」なんて…\nクスクスクス…", 5016, 0, 0, 129911, 5, 11, 5, 0.5);
