INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", 0, "vo_minigame_1013_top_talk_6_001", 6010, "", "", "vo_minigame_1013", 0, 21, 6, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 6011, 0, 0, 129911, 6, 11, 6, 0.8);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", "", "", 6012, "", "", 0, "", 91, 6, "");
