INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (1, "drama_talk_surprise_loop_shy", "drama_talk_surprise_in_shy", 6014, "", 0.2, 129811, 0, 3, 6, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", 0, "vo_minigame_1013_top_talk_6_002", 6015, "", "", "vo_minigame_1013", 0, 21, 6, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 6016, 0, 0, 129811, 9, 11, 6, 0.3);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", "", "", 6017, "", "", 0, "", 91, 6, "");
