INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "私の班のみなさんも\n変わらず訓練に励んで\nいるようですわね\n殊勝なことです", 7006, 0, 0, 129911, 6, 11, 7, 0.3);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", "", "", 7007, "", "", 0, "", 91, 7, "");
