INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES ("", 0, "vo_minigame_1013_top_talk_7_002", 7015, "", "", "vo_minigame_1013", 0, 21, 7, "");
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "彼らが私に逆らわずに\n努力したからこそ、\n得たものもありますし\n…感謝しておきますわ", 7016, 0, 0, 129911, 6, 11, 7, 0.5);
