INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (0, 1, "くっ、そう言われると\n悔しいな…！\nならこの行軍訓練で\n逆転してやるぜ！", 8016, 0, 0, 129811, 7, 11, 8, 0.3);
